The Vox program below simulates round-robin scheduling of three jobs with a quantum of 3 ticks. Run the simulation exactly as coded.

```vox
fn main() to int {
    let mut remaining: list[int] = [7, 4, 9]
    let quantum = 3
    let mut ticks = 0
    let mut finished_at_sum = 0
    let mut done = 0
    while done < 3 {
        let mut i = 0
        while i < 3 {
            let left = remaining[i].unwrap()
            if left > 0 {
                let slice = if left < quantum { left } else { quantum }
                ticks = ticks + slice
                remaining[i] = left - slice
                if remaining[i].unwrap() == 0 {
                    done = done + 1
                    finished_at_sum = finished_at_sum + ticks
