The Vox program below simulates a small stack machine that runs a list of instructions on a fixed-size stack. Run the simulation exactly as coded.

```vox
type Op =
    | Push(n: int)
    | Add
    | Mul
    | Dup

fn main() to int {
    let prog: list[Op] = [Push(2), Push(3), Add, Dup, Mul, Push(4), Add]
    let mut stack: list[int] = [0, 0, 0, 0]
    let mut sp = 0
    for op in prog {
        match op {
            Push(n) => {
                stack[sp] = n
                sp = sp + 1
            }
            Dup => {
                stack[sp] = stack[sp - 1].unwrap()
                sp = sp + 1
            }
            Add => {
                stack[sp - 2] = stack[sp - 2].unwrap() + stack[sp - 1].unwrap()
                sp = sp - 1
            }
            Mul => {
                stack[sp - 2] = stack[sp - 2].unwrap() * stack[sp - 1].unwrap()
                sp = sp - 1
            }
        }
    }
    return stack[sp - 1].unwrap() * 100 + sp
}
